using System.IO.Abstractions.TestingHelpers;
using Mutagen.Bethesda.Plugins;
using Mutagen.Bethesda.Plugins.Binary.Parameters;
using Mutagen.Bethesda.Plugins.Order;
using Mutagen.Bethesda.Plugins.Records;
using Mutagen.Bethesda.Starfield;
using Shouldly;
using Xunit;

namespace Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield;

// A scene camera shot writes Use Look Target Alias (MPCD) before Ignore Collision (AIDT), as xEdit defines it and as
// sfta03.esm stores it in all 5 shots that set both (Starfield.esm never sets both). Mutagen wrote AIDT first, so M3
// counted those SCEN as reordered. The test reads SFTA03_1090_Mantis_Boss (FD01232F:sfta03.esm) whole, from a plugin
// made of sfta03.esm's real header and that record (masters Starfield.esm and the Medium sfbgs003.esm; sfta03 is Medium
// itself), with both readers, and writes the record back byte for byte.
public class SceneCameraShotMarkerOrderTests
{
    private static readonly ModKey Plugin = ModKey.FromFileName("sfta03.esm");

    private const string Tes4 = "";

    // SFTA03_1090_Mantis_Boss (FD01232F:sfta03.esm)
    private const string Scen = "";

    private static byte[] Hex(string hex) => Convert.FromHexString(hex);

    private static byte[] Group(byte[] label, int groupType, byte[] content)
    {
        var s = new MemoryStream();
        s.Write("GRUP"u8);
        s.Write(BitConverter.GetBytes(24 + content.Length));
        s.Write(label);
        s.Write(BitConverter.GetBytes(groupType));
        s.Write(new byte[8]);
        s.Write(content);
        return s.ToArray();
    }

    // The scene's quest is a stand-in (the real SFTA03 quest, FD0121BE, is 50 KB): same FormID and form version, EDID
    // only. Scenes live in their quest's child group.
    private static byte[] QuestWithScene()
    {
        var edid = "EDID"u8.ToArray().Concat(BitConverter.GetBytes((ushort)7)).Concat("SFTA03\0"u8.ToArray()).ToArray();
        var quest = new MemoryStream();
        quest.Write("QUST"u8);
        quest.Write(BitConverter.GetBytes(edid.Length));
        quest.Write(new byte[4]);
        quest.Write(BitConverter.GetBytes(0xFD0121BEu));
        quest.Write(Hex("7E3420004602")); // version control and form version 582, as in sfta03.esm
        quest.Write(new byte[2]);
        quest.Write(edid);
        var children = Group(BitConverter.GetBytes(0xFD0121BEu), 10, Hex(Scen));
        return Group("QUST"u8.ToArray(), 0, quest.ToArray().Concat(children).ToArray());
    }

    // The bytes of the first record of a type anywhere in a written plugin
    private static byte[] RecordBytes(byte[] file, string type)
    {
        int p = 24 + BitConverter.ToInt32(file, 4);
        while (p + 24 <= file.Length)
        {
            var sig = System.Text.Encoding.ASCII.GetString(file, p, 4);
            int size = BitConverter.ToInt32(file, p + 4);
            if (sig == "GRUP") { p += 24; continue; }
            if (sig == type) return file.AsSpan(p, 24 + size).ToArray();
            p += 24 + size;
        }
        throw new InvalidOperationException(type + " not written");
    }

    [Fact]
    public void CameraShot_UseLookTargetAliasBeforeIgnoreCollision()
    {
        var fs = new MockFileSystem();
        var dir = System.IO.Path.Combine("C:", "Data");
        fs.Directory.CreateDirectory(dir);
        var path = System.IO.Path.Combine(dir, Plugin.FileName);
        fs.File.WriteAllBytes(path, Hex(Tes4).Concat(QuestWithScene()).ToArray());
        var lo = new LoadOrder<IModMasterStyledGetter>(new IModMasterStyledGetter[]
        {
            new KeyedMasterStyle(ModKey.FromFileName("Starfield.esm"), MasterStyle.Full),
            new KeyedMasterStyle(ModKey.FromFileName("sfbgs003.esm"), MasterStyle.Medium),
            new KeyedMasterStyle(Plugin, MasterStyle.Medium),
        });
        var param = new BinaryReadParameters { FileSystem = fs, MasterFlagsLookup = lo };
        var mods = new IStarfieldModGetter[]
        {
            StarfieldMod.CreateFromBinary(path, StarfieldRelease.Starfield, param),
            StarfieldMod.CreateFromBinaryOverlay(path, StarfieldRelease.Starfield, param),
        };
        foreach (var mod in mods)
        {
            var scen = mod.Quests.ShouldHaveSingleItem().Scenes.ShouldHaveSingleItem();
            scen.EditorID.ShouldBe("SFTA03_1090_Mantis_Boss");
            var shots = scen.Actions.OfType<ICameraSceneActionGetter>().SelectMany(a => a.CameraShots ?? Enumerable.Empty<ICameraSceneShotGetter>()).ToList();
            shots.ShouldContain(s => s.UseLookTargetAlias && s.IgnoreCollision);

            var outPath = System.IO.Path.Combine("C:", "Out", Plugin.FileName);
            fs.Directory.CreateDirectory(System.IO.Path.GetDirectoryName(outPath)!);
            mod.WriteToBinary(outPath, new BinaryWriteParameters
            {
                FileSystem = fs,
                MasterFlagsLookup = lo,
                MastersListContent = MastersListContentOption.NoCheck,
                MastersListOrdering = new MastersListOrderingByLoadOrder(mod.MasterReferences.Select(m => m.Master)),
            });
            RecordBytes(fs.File.ReadAllBytes(outPath), "SCEN").ShouldBe(Hex(Scen));
        }
    }
}
